fn fib(n: u32) -> Option<u128> {
    if n == 0 {
        return Some(0);
    }

    let mut a: u128 = 0;
    let mut b: u128 = 1;

    for _ in 1..n {
        let next = a.checked_add(b)?;
        a = b;
        b = next;
    }

    Some(b)
}

